import re
from urllib.parse import urljoin
base='https://www.incontrodanville.com/'
urls=set()
for f in ['home.html','catering.html']:
    h=open(f,encoding='utf-8',errors='ignore').read()
    for pat in [r'<img[^>]+src=\"([^\"]+)\"', r'data-src=\"([^\"]+)\"', r'srcset=\"([^\"]+)\"', r'background-image:\s*url\(([^)]+)\)', r'og:image\" content=\"([^\"]+)\"', r'data-bg=\"([^\"]+)\"']:
        for m in re.finditer(pat,h):
            v=m.group(1)
            if 'srcset' in pat or ',' in v and ' ' in v:
                parts=[p.strip().split(' ')[0] for p in v.split(',')]
            else:
                parts=[v]
            for p in parts:
                p=p.strip().strip('\'\"')
                if not p or p.startswith('data:'): continue
                u=urljoin(base,p)
                if re.search(r'\.(jpe?g|png|webp|gif|svg|avif)(\?|$)',u,re.I):
                    urls.add(u)
for u in sorted(urls): print(u)
print('TOTAL',len(urls))
"

